  camera.position.z = 3;



// ________________________________________________________________________________________________________________________________________________

    // Создаем переменные для точки и радиуса
  let point = new THREE.Vector3(0, 0, 0);
  let radius = 1;

  // Создаем функцию для генерации случайной точки внутри заданного радиуса
  function generateRandomPointInRadius(radius) {
    let angle1 = Math.random() * 2 * Math.PI;
    let angle2 = Math.random() * 2 * Math.PI;
    let x = radius * Math.sin(angle1) * Math.cos(angle2);
    let y = radius * Math.sin(angle1) * Math.sin(angle2);
    let z = radius * Math.cos(angle1);
    return new THREE.Vector3(x, y, z);
  }

  // Инициализируем переменные для генерации случайной точки
  let randomPoint = generateRandomPointInRadius(radius);
  let dist = point.distanceTo(randomPoint);
  let t = 0;

  // Создаем функцию для анимации точки
  function animatePoint() {
    t += 0.01;
    if (t > 1) {
      randomPoint = generateRandomPointInRadius(radius);
      dist = point.distanceTo(randomPoint);
      t = 0;
    }
    let newPos = point.clone().lerp(randomPoint, t);
    let moveDist = newPos.distanceTo(point);
    if (moveDist >= dist) {
      randomPoint = generateRandomPointInRadius(radius);
      dist = point.distanceTo(randomPoint);
      t = 0;
    }
    point.copy(newPos);
  }

  // Добавляем точку на сцену
  let pointGeometry = new THREE.SphereGeometry(0.2, 32, 32);
  let pointMaterial = new THREE.MeshBasicMaterial({color: 0xff0000});
  let pointMesh = new THREE.Mesh(pointGeometry, pointMaterial);
  pointMesh.position.set(point.x, point.y, point.z);
  scene.add(pointMesh);


// ________________________________________________________________________________________________________________________________________________



  let uniforms = {
    mouseCoord: {type:'v3', value: new THREE.Vector3()},
    tex: { type:'t', value:texture },
    res: { type:'v2', value:new THREE.Vector2(window.innerWidth,window.innerHeight)}
  };

  const planeGeometry = new THREE.PlaneGeometry(1000, 1000);
  const planeMaterial = new THREE.ShaderMaterial({
    uniforms:uniforms, 
    fragmentShader:shaderCode,
    side: THREE.DoubleSide
  });
  const planeMesh = new THREE.Mesh(planeGeometry, planeMaterial);
  scene.add(planeMesh);
  planeMesh.position.set(0, 0, -85);


  controls.addEventListener('change', function() {
    planeMesh.quaternion.copy(camera.quaternion);
  });

  let targetX = 0;
  let targetY = 0;
  let currentX = 0;
  let currentY = 0;

  function update() {
      requestAnimationFrame(update);
      const diffX = targetX - currentX;
      const diffY = targetY - currentY;
      const distance = Math.sqrt(diffX * diffX + diffY * diffY);
      const speed = distance / 10;
      if (distance < 1.0) {
          currentX = targetX;
          currentY = targetY;
      } else {
          currentX += speed * diffX / distance;
          currentY += speed * diffY / distance;
      }
  }
  update();

  document.addEventListener('mousemove', (event) => {
    targetX = event.clientX;
    targetY = event.clientY;
    uniforms.mouseCoord.value.x = currentX;
    uniforms.mouseCoord.value.y = -currentY + window.innerHeight;
  });


  function animate() {
    requestAnimationFrame(animate);
    animatePoint();
    pointMesh.position.set(point.x, point.y, point.z);
    controls.update();
    uniforms.mouseCoord.value.x = currentX;
    uniforms.mouseCoord.value.y = -currentY + window.innerHeight;
    renderer.render(scene, camera);
  }
  animate();
});

//优化人脸稳定性输出代码
if(id >= 0)
{
PF_Rect_S curFaceRect = pAiFaceRectInfo->faceRect[id].faceRect;
if(stRect.left == 0 && stRect.right == 0 && stRect.top == 0 && stRect.bottom == 0)
{
stRect = curFaceRect;
}
else
{
int curWidth = curFaceRect.right - curFaceRect.left;
int curHeight = curFaceRect.bottom - curFaceRect.top;
int maxWidth = stRect.right - stRect.left;
int maxHeight = stRect.bottom - stRect.top;
if(curWidth < maxWidth * 0.8 || curHeight < maxHeight * 0.8) //新检测到人脸大小太小
{
if(cnt == 0)
{
cnt = 3; //直接使用上一次稳定的人脸框
}
continue;
}
else
{
stRect.left = (stRect.left + curFaceRect.left) / 2;
stRect.right = (stRect.right + curFaceRect.right) / 2;
stRect.top = (stRect.top + curFaceRect.top) / 2;
stRect.bottom = (stRect.bottom + curFaceRect.bottom) / 2;
//限制人脸框的范围
if(stRect.left < 0) stRect.left = 0;
if(stRect.top < 0) stRect.top = 0;
if(stRect.right > viRect.width) stRect.right = viRect.width;
if(stRect.bottom > viRect.height) stRect.bottom = viRect.height;
}
}
//更新当前使用的人脸框
id = -1;
for(i=0; i<pAiFaceRectInfo->faceCnt; i++)
{
if(stRect.left >= pAiFaceRectInfo->faceRect[i].faceRect.left
&& stRect.right <= pAiFaceRectInfo->faceRect[i].faceRect.right
&& stRect.top >= pAiFaceRectInfo->faceRect[i].faceRect.top
&& stRect.bottom <= pAiFaceRectInfo->faceRect[i].faceRect.bottom)
{
id = i;
break;
}
}
if(id >= 0)
{
pAiFaceRectInfo->faceCnt = 1;
pAiFaceRectInfo->faceRect[0] = pAiFaceRectInfo->faceRect[id];
}
else
{
continue;
}
}

//获取人脸框
PF_Rect_S faceRect = {0};
if(pAiFaceRectInfo->faceCnt > 0)
{
faceRect = pAiFaceRectInfo->faceRect[0].faceRect;
}
else
{
usleep(501000);
continue;
}

//根据人脸框位置计算VGRect
VGRect_S vgRect = {0};
float vgXRatio = 1.0 * viRect.width / VC_GetVGInfo()->VGWidth;
float vgYRatio = 1.0 * viRect.height / VC_GetVGInfo()->VGHeight;
vgRect.left = faceRect.left / vgXRatio;
vgRect.top = faceRect.top / vgYRatio;
vgRect.right = faceRect.right / vgXRatio;
vgRect.bottom = faceRect.bottom / vgYRatio;

//根据VGRect计算ExpWin
expWin.h_offs = vgRect.left - VC_GetVGInfo()->VGLeft;
expWin.v_offs = vgRect.top - VC_GetVGInfo()->VGTop;
expWin.h_size = vgRect.right - vgRect.left;
expWin.v_size = vgRect.bottom - vgRect.top;

//限制ExpWin位置和大小
if(expWin.h_offs < 0)
{
expWin.h_offs = 0;
expWin.h_size = vgRect.right - VC_GetVGInfo()->VGLeft;
}
if(expWin.v_offs < 0)
{
expWin.v_offs = 0;
expWin.v_size = vgRect.bottom - VC_GetVGInfo()->VGTop;
}
if(expWin.h_offs + expWin.h_size > viRect.width)
{
expWin.h_size = viRect.width - expWin.h_offs;
}
if(expWin.v_offs + expWin.v_size > viRect.height)
{
expWin.v_size = viRect.height - expWin.v_offs;
}

//发送ExpWin到图像处理线程
VC_ImageManagerSetExpWin(&expWin);
}//end while

